/*
A_f = 1/2 sqrt((a_f+(b_f+c_f)) (c_f-(a_f-b_f)) (c_f+(a_f-b_f)) (a_f+(b_f-c_f)))
C_f = 1/(4 A_f) [b_f²+c_f²-a_f², c_f²+a_f²-b_f², a_f²+b_f²-c_f²]

where

a_i ∈ ℝ
b_i ∈ ℝ
c_i ∈ ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    VectorD A;
    std::vector<Eigen::Matrix<DT, 1, 3>> C;

    heartlib(
        const std::vector<double> & a,
        const std::vector<double> & b,
        const std::vector<double> & c)
    {
        const long dim_0 = a.size();
        assert( b.size() == dim_0 );
        assert( c.size() == dim_0 );
        // A_f = 1/2 sqrt((a_f+(b_f+c_f)) (c_f-(a_f-b_f)) (c_f+(a_f-b_f)) (a_f+(b_f-c_f)))
        A.resize(dim_0);
        for( int f=1; f<=dim_0; f++){
            A[f-1] = 1 / DT(2) * sqrt((a.at(f-1) + (b.at(f-1) + c.at(f-1))) * (c.at(f-1) - (a.at(f-1) - b.at(f-1))) * (c.at(f-1) + (a.at(f-1) - b.at(f-1))) * (a.at(f-1) + (b.at(f-1) - c.at(f-1))));
        }
        // C_f = 1/(4 A_f) [b_f²+c_f²-a_f², c_f²+a_f²-b_f², a_f²+b_f²-c_f²]
        C.resize(dim_0);
        for( int f=1; f<=dim_0; f++){
            Eigen::Matrix<DT, 1, 3> C_f_0;
            C_f_0 << pow(b.at(f-1), 2) + pow(c.at(f-1), 2) - pow(a.at(f-1), 2), pow(c.at(f-1), 2) + pow(a.at(f-1), 2) - pow(b.at(f-1), 2), pow(a.at(f-1), 2) + pow(b.at(f-1), 2) - pow(c.at(f-1), 2);
            C.at(f-1) = 1 / DT((4 * A[f-1])) * C_f_0;
        }
    }
};

